module down_counter_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg enable;
    reg [3:0] preset;
    reg reset;
    wire [3:0] count;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    down_counter dut (
        .clk(clk),
        .enable(enable),
        .preset(preset),
        .reset(reset),
        .count(count)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            @(negedge clk);
            reset = 1;
            enable = 0;
            preset = 4'h0;
            @(negedge clk);
            reset = 0;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Reset to preset value", test_num);
            reset_dut();

            @(negedge clk);
            preset = 4'hA;
            reset = 1;
            @(negedge clk);
            reset = 0;

            #1;
            #1;

            check_outputs(4'hA);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Single step decrement", test_num);


            @(negedge clk);
            preset = 4'hF;
            reset = 1;
            @(negedge clk);
            reset = 0;


            @(negedge clk);
            enable = 1;
            @(negedge clk);
            enable = 0;

            #1;
            #1;

            check_outputs(4'hE);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Multiple step decrement", test_num);


            @(negedge clk);
            preset = 4'h5;
            reset = 1;
            @(negedge clk);
            reset = 0;


            @(negedge clk);
            enable = 1;
            repeat(3) @(negedge clk);
            enable = 0;

            #1;
            #1;

            check_outputs(4'h2);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Verify counter stays same when enable is low", test_num);


            @(negedge clk);
            preset = 4'h8;
            reset = 1;
            @(negedge clk);
            reset = 0;


            @(negedge clk);
            enable = 0;
            repeat(5) @(negedge clk);

            #1;
            #1;

            check_outputs(4'h8);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Verify wrap-around from 0 to F", test_num);


            @(negedge clk);
            preset = 4'h0;
            reset = 1;
            @(negedge clk);
            reset = 0;


            @(negedge clk);
            enable = 1;
            @(negedge clk);
            enable = 0;

            #1;
            #1;

            check_outputs(4'hF);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Intermittent enable signal", test_num);


            @(negedge clk);
            preset = 4'h7;
            reset = 1;
            @(negedge clk);
            reset = 0;


            @(negedge clk); enable = 1;

            @(negedge clk); enable = 0;

            @(negedge clk); enable = 1;

            @(negedge clk); enable = 1;
            @(negedge clk); enable = 0;

            #1;
            #1;

            check_outputs(4'h4);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Full 16-step cycle", test_num);


            @(negedge clk);
            preset = 4'hF;
            reset = 1;
            @(negedge clk);
            reset = 0;


            @(negedge clk);
            enable = 1;
            repeat(16) @(negedge clk);
            enable = 0;

            #1;
            #1;

            check_outputs(4'hF);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("down_counter Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [3:0] expected_count;
        begin
            if (expected_count === (expected_count ^ count ^ expected_count)) begin
                $display("PASS");
                $display("  Outputs: count=%h",
                         count);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: count=%h",
                         expected_count);
                $display("  Got:      count=%h",
                         count);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, enable, preset, reset, count);
    end

endmodule

